// The connected board's work, put together: its cards, the builder and the
// coach in the cards (each off until the owner switches it on), with their
// working copies in a folder next to the project. None without a connected
// board.
import { basename, dirname, join } from "node:path";
import { Workspace } from "@software-factory/core";
import { realCli } from "../add-ons/github/github.js";
import { Refused } from "../refused.js";
import { cardsFor } from "../cards/cards-for.js";
import { readBoard } from "../connect/board-file.js";
import { BoardWork } from "./board-work.js";
import { Jobs } from "./jobs.js";
import { githubPullRequests } from "./pull-requests.js";
export function workFor(settings) {
    const { root, project, cli, claude, available, onChange } = settings;
    const found = cardsFor(root, cli);
    if ("problem" in found)
        return null;
    const copies = join(dirname(project), `${basename(project)}-factory-copies`);
    const pullRequests = githubPullRequests(cli, found.repository);
    const copyOf = async (name) => new Workspace({
        source: project,
        workspaces: copies,
        baseBranch: await pullRequests.baseBranch(),
    }, name);
    const jobs = new Jobs({
        cards: found.cards,
        pullRequests,
        claude,
        repository: found.repository,
        available,
        copies: { chat: () => copyOf("chat"), build: () => copyOf("build") },
    });
    return new BoardWork({ cards: found.cards, pullRequests, jobs, onChange });
}
// The session's board work: connected once a factory with a board opens,
// connected again when the board changes, stopped when the factory closes.
export class ConnectedWork {
    settings;
    work = null;
    // The board it was connected to, to see when it changes.
    board = "";
    // From the session's options: the project and the coaches' Claude Code;
    // the GitHub CLI is the real one unless a test gives one.
    constructor(options) {
        this.settings = {
            project: options.project,
            cli: options.cli ?? realCli(),
            claude: options.coach.claude,
            available: options.available,
            onChange: options.onChange,
        };
    }
    view() {
        return this.work?.view() ?? null;
    }
    // Connects to the factory's board, again when the board changed (the
    // owner connected another one, or changed board.json by hand).
    connect(root) {
        const board = JSON.stringify(readBoard(root));
        if (board === this.board)
            return;
        this.stop();
        this.board = board;
        this.work = workFor({ ...this.settings, root });
        this.work?.start();
    }
    stop() {
        this.work?.stop();
        this.work = null;
        this.board = "";
    }
    // For the Board tab's buttons.
    orRefuse() {
        if (!this.work)
            throw new Refused("Connect a board first: the builder works its cards.");
        return this.work;
    }
}
